mapper.select:
SELECT
p.id                            AS id,
p.id                            AS patient_id,
p.name                          AS keyword,
r.encounter_id                  AS encounter_id,
r.bus_no                        AS bus_no,
r.org_id                        AS organization_id,
r.location_id                   AS destination_location_id,
r.category_enum                 AS service_type_code,
r.status_enum                   AS appointment_kind,
r.created_at                    AS created_at,
r.req_authored_time             AS start_instant
FROM med_medication_request r
JOIN adm_patient p ON p.id = r.patient_id
WHERE r.is_deleted = 0


    AND r.patient_id = #{query.patient_id}



    AND r.encounter_id = #{query.encounter_id}



    AND r.org_id = #{query.organization_id}



    AND r.status_enum = #{query.appointment_kind}



    AND r.category_enum = #{query.service_type_code}



    AND r.location_id = #{query.destination_location_id}



    AND r.req_authored_time >= #{query.start_time}



    AND r.req_authored_time <= #{query.end_time}


ORDER BY r.req_authored_time DESC
